pub(crate) const STYLES: &str = r#"
.df-character{--gold:#d9b77a;--muted:#b4aca0;--ink:#141310;position:relative;isolation:isolate;min-height:100svh;background:var(--ink);color:#f4eddf;font-family:Georgia,'Times New Roman',serif;overflow:hidden}
.df-character *{box-sizing:border-box;min-width:0}.df-character [hidden]{display:none!important}.df-character p,.df-character h1,.df-character h2,.df-character button,.df-character dd{overflow-wrap:anywhere}.df-character .character-backdrop{position:absolute;inset:0;width:100%;height:820px;object-fit:cover;object-position:center 42%;z-index:-3;opacity:1}.df-character:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,#12100a80,#14131030 180px,#141310d9 520px,#141310 800px),linear-gradient(90deg,#11100db3,transparent 75%)}
.df-character .character-header{padding:22px 4vw;display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:1px solid #d9b77a24;background:linear-gradient(#11100a99,transparent)}.df-character .character-brand{font-size:26px;letter-spacing:-1px;color:#efce91}.df-character .character-brand span{color:#eee5d5}.df-character .character-overline{font:10px/1.7 system-ui,sans-serif;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold)}
.df-character .character-hero{width:min(1380px,92%);margin:auto;padding:90px 0 30px}.df-character h1{font-size:clamp(40px,5vw,66px);font-weight:400;letter-spacing:-1.8px;line-height:1.06;margin:12px 0 16px;text-shadow:0 3px 35px #000}.df-character .character-description{max-width:600px;color:#eee5d5;font-size:16px;line-height:1.65;margin:0;text-shadow:0 2px 8px #000}.df-character .character-layout{width:min(1380px,92%);margin:auto;display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:start;padding-bottom:35px}.df-character .character-workshop,.df-character .character-groups{display:grid;gap:18px}.df-character .character-panel{border:1px solid #c7a86b4d;border-radius:10px;background:linear-gradient(135deg,#24211bee,#181713f5);padding:22px;box-shadow:0 16px 45px #0004}.df-character h2{font-size:23px;line-height:1.3;font-weight:400;margin:0 0 15px;color:#e8d7b3}.df-character .character-group-description{font:12px/1.6 system-ui,sans-serif;color:var(--muted);margin:0 0 17px}.df-character .character-summary{position:sticky;top:24px}.df-character .character-portrait{display:block;width:100%;height:210px;object-fit:cover;object-position:center 35%;border:1px solid #cba46673;border-radius:6px;background:#1d1c17;margin:16px 0 8px}.df-character .character-art-credit{font:10px/1.6 system-ui,sans-serif;color:#a99c84;margin:8px 0 18px}.df-character .character-status{font-size:21px;margin-bottom:10px}.df-character .character-message{font:12px/1.6 system-ui,sans-serif;color:#d8cbb2;margin:0 0 17px}.df-character[data-status=rejected] .character-message{color:#f0b9a3}.df-character[data-status=ready] .character-status,.df-character[data-status=locked] .character-status{color:#b5ddc2}
.df-character .df-ui-field{margin-top:14px;display:grid;gap:6px}.df-character .df-ui-field label{display:grid;gap:7px;font:11px/1.6 system-ui,sans-serif;color:#c5b99e}.df-character input{width:100%;min-height:48px;padding:12px 14px;border:1px solid #a3916b59;border-radius:6px;color:#f4eddf;background:#161510;font:16px/1.5 system-ui,sans-serif}.df-character input[readonly]{color:#b4aca0;background:#1d1c17}.df-character input[aria-invalid=true]{border-color:#dfa390}.df-character .df-ui-feedback{font:12px/1.6 system-ui,sans-serif;color:#dcc393;margin:0;min-height:0}.df-character .df-ui-feedback:empty{display:none}
.df-character .character-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.df-character .character-option{position:relative;border:1px solid #a394713d;border-radius:8px;padding:15px;background:#15151199;display:grid;grid-template-columns:64px minmax(0,1fr);column-gap:13px;row-gap:7px;align-content:start;transition:border-color .15s,background .15s}.df-character .character-option[data-selected=true]{border-color:#d0a965;background:linear-gradient(135deg,#86633330,#171611);box-shadow:inset 0 0 0 1px #d9b77a24}.df-character .character-option[data-selected=true] .option-availability:after{content:' · Selected';color:#f3d28b}.df-character .option-portrait{grid-column:1;grid-row:1 / span 3;width:64px;height:86px;object-fit:cover;border-radius:6px;border:1px solid #cba46673;background:#24211b}.df-character .option-description{grid-column:2;grid-row:2;font:12px/1.6 system-ui,sans-serif;color:#d8cbb2;margin:0}.df-character .option-availability{grid-column:2;grid-row:3;font:10px/1.6 system-ui,sans-serif;color:#a99c84;margin:0}.df-character button{touch-action:manipulation;min-height:48px;width:100%;font:13px/1.5 system-ui,sans-serif;letter-spacing:.2px;border:1px solid #a98b574d;border-radius:6px;padding:11px 14px;color:#ede2cb;background:#29251e;cursor:pointer;box-shadow:inset 0 1px 0 #fff1}.df-character button:hover:enabled{background:#42382a;border-color:#e5bd77}.df-character button[aria-pressed=true]{border-color:#e9c78d;background:linear-gradient(135deg,#e3c592,#b99151);color:#211b11;font-weight:650}.df-character button:disabled{cursor:default;color:#9c9488;border-color:#8c806b3d;background:#1d1c17;box-shadow:none}.df-character :focus-visible{outline:3px solid #f1d69b;outline-offset:4px}.df-character .character-facts{margin:0 0 18px}.df-character .character-fact{display:flex;justify-content:space-between;gap:15px;border-top:1px solid #d9b77a24;padding:10px 0;font:12px/1.6 system-ui,sans-serif}.df-character dt{color:#aaa08b}.df-character dd{margin:0;text-align:right;color:#e5d6b8}.df-character .character-actions{display:grid;gap:10px}.df-character .character-reference{width:min(1380px,92%);margin:0 auto 30px;border-top:1px solid #b69b6355;padding-top:25px}.df-character summary{min-height:44px;color:#dfbd80;cursor:pointer;font:13px/1.6 system-ui,sans-serif}.df-character .character-reference img{display:block;width:100%;max-width:1000px;border:1px solid #ad925d55}.df-character .character-connection{padding:10px 4vw 30px;text-align:center;color:#a89c84;font:10px/1.7 system-ui,sans-serif}.df-character .character-fixture-controls{width:min(1380px,92%);margin:0 auto 30px;display:flex;flex-wrap:wrap;gap:10px}.df-character .character-fixture-controls button{width:auto}.df-character .character-fixture-output{width:min(1380px,92%);margin:0 auto 24px;color:#b4aca0;font:12px/1.7 system-ui,sans-serif}
.df-character .character-portrait,.df-character .option-portrait{position:relative;overflow:hidden;flex-shrink:0;background:radial-gradient(ellipse at 50% 35%,#49412d,#1d1c17 75%)}.df-character .portrait-bitmap{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover;object-position:center 35%;border-radius:inherit}.df-character .portrait-fallback{position:absolute;inset:0;display:block;color:#d7bc84}.df-character .portrait-fallback:before{content:'';position:absolute;left:50%;top:20%;transform:translateX(-50%);width:26%;height:29%;border:1px solid currentColor;border-radius:50%;background:#c5ab7433}.df-character .portrait-fallback:after{content:'';position:absolute;left:50%;top:54%;transform:translateX(-50%);width:65%;height:47%;border:1px solid currentColor;border-radius:50% 50% 0 0;background:#c5ab7422}.df-character .character-portrait .portrait-fallback{max-width:140px;left:50%;transform:translateX(-50%);width:100%}
.df-character .identity-panel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}.df-character .identity-panel h2{grid-column:1 / -1;margin-bottom:0}.df-character .character-option button{grid-column:2;grid-row:1;text-align:left}.df-character button[aria-busy=true]{border-style:dashed}.df-character .character-actions button:enabled{background:linear-gradient(135deg,#e3c592,#b99151);color:#211b11;border-color:#e9c78d;font-weight:650;box-shadow:0 5px 20px #9f6b3026,inset 0 1px 0 #fff6}.df-character .character-actions button:hover:enabled,.df-character button[aria-pressed=true]:hover:enabled{background:#edcea0}.df-character .character-option:focus-within{border-color:#e5bd77}
.df-character .character-appearance{position:relative;overflow:hidden;border-color:#b9975c70;background:linear-gradient(135deg,#31291d,#1c1a16 72%)}.df-character .character-appearance:before{content:'';position:absolute;inset:0 0 auto;height:3px;background:linear-gradient(90deg,transparent,#e6bd78,transparent)}.df-character .character-appearance h2{margin:5px 0 10px}.df-character .character-appearance .character-group-description{max-width:630px;margin-bottom:20px}.df-character .character-appearance .df-ui-field{margin-top:13px}.df-character .character-appearance-note{font:11px/1.6 system-ui,sans-serif;color:#c5b99e;border-top:1px solid #d9b77a24;margin:20px 0 0;padding-top:13px}
@media(max-width:1000px){.df-character .character-layout{grid-template-columns:minmax(0,1fr) 260px;gap:18px}.df-character .character-panel{padding:20px}.df-character .character-options{grid-template-columns:1fr}.df-character .character-hero{padding-top:65px}}
@media(max-width:700px){.df-character .character-header{padding:17px 5vw;align-items:start;gap:14px}.df-character .character-header .character-overline{max-width:120px;text-align:right;font-size:8px;letter-spacing:1.5px}.df-character .character-brand{font-size:22px}.df-character .character-backdrop{height:520px;object-position:center top}.df-character:before{background:linear-gradient(180deg,#14131070,#14131040 120px,#141310dd 320px,#141310 500px)}.df-character .character-hero{width:90%;padding:58px 0 24px}.df-character h1{letter-spacing:-1px;font-size:37px;margin:10px 0 12px}.df-character .character-description{font-size:14px;line-height:1.6}.df-character .character-layout{display:flex;flex-direction:column;width:90%;gap:18px}.df-character .character-workshop,.df-character .character-summary{width:100%;position:static}.df-character .character-workshop,.df-character .character-groups{gap:16px}.df-character .identity-panel{grid-template-columns:1fr}.df-character .character-options{grid-template-columns:1fr;gap:10px}.df-character .character-option{padding:13px;column-gap:12px}.df-character .character-portrait{height:210px}.df-character .character-panel{padding:18px;border-radius:8px}.df-character h2{font-size:21px;margin-bottom:12px}.df-character .identity-panel h2{margin-bottom:0}.df-character .character-overline{font-size:9px;letter-spacing:2px}.df-character .character-reference{width:90%;padding-top:18px}.df-character .character-fixture-controls{width:90%}.df-character .character-fixture-controls button{flex:1 1 130px}.df-character .character-fixture-output{width:90%}}
@media(max-width:360px){.df-character .character-brand{font-size:20px}.df-character .character-header .character-overline{max-width:105px;font-size:7px}.df-character h1{font-size:33px}.df-character .character-option{grid-template-columns:52px minmax(0,1fr);column-gap:10px}.df-character .option-portrait{width:52px;height:74px}}
@media(prefers-reduced-motion:reduce){.df-character *,.df-character *:before,.df-character *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
"#;
